    let convertedText = "";
    let inQuotes = false;
    for (let i = 0; i < text.length; i++) {
      let ch = text.charAt(i);
      if (ch === '"') {
        inQuotes = !inQuotes;
      } else if (ch === " " && !inQuotes) {
        ch = "\n";
      }
      convertedText += ch;
    }
    text = convertedText;
  }

  const lines = text.trim().split("\n");
  return lines.map((line) => {
    const parts = line.trim().split("=");
    return [parts[0], (parts[1] || "").replace(/^"/, "").replace(/"$/, "")];
  });
}

